int parse_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4)
        return -1;

    int len;
    if (sscanf(line, "%4hX", &len) != 1)
        return -1;

    if (len == 0 && memcmp(line, "0000", 4) == 0) {
        *out = line + 4;
        return 0;
    }

    if (bufflen < len + 4)
        return -1;

    git_pkt *pkt = (git_pkt *)malloc(sizeof(git_pkt));
    if (!pkt)
        return -1;

    pkt->data = (char *)malloc(len);
    if (!pkt->data) {
        free(pkt);
        return -1;
    }

    memcpy(pkt->data, line + 4, len);
    pkt->len = len;

    pkt->next = *head;
    *head = pkt;

    *out = line + 4 + len;
    return len + 4;
}

int git_pkt_parse(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    const char *start = line;
    const char *end = line + bufflen;
    const char *current = start;
    git_pkt *pkt;
    size_t len;

    if (bufflen < 4)
        return GIT_PKT_ERROR_SHORT;

    if (memcmp(current, "ACK", 3) == 0) {
        current += 3;
        if (current + 4 > end)
            return GIT_PKT_ERROR_SHORT;
        if (sscanf(current, "%zu", &len) != 1)
            return GIT_PKT_ERROR_PARSE;
        current += 4;
        pkt = git_pkt_new(GIT_PKT_ACK, current, len);
    }
    else if (memcmp(current, "DATA", 4) == 0) {
        current += 4;
        if (current + 4 > end)
            return GIT_PKT_ERROR_SHORT;
        if (sscanf(current, "%zu", &len) != 1)
            return GIT_PKT_ERROR_PARSE;
        current += 4;
        pkt = git_pkt_new(GIT_PKT_DATA, current, len);
    }
    else if (memcmp(current, "SIDEBAND", 8) == 0) {
        current += 8;
        if (current + 4 > end)
            return GIT_PKT_ERROR_SHORT;
        if (sscanf(current, "%zu", &len) != 1)
            return GIT_PKT_ERROR_PARSE;
        current += 4;
        pkt = git_pkt_new(GIT_PKT_SIDEBAND, current, len);
    }
    else if (memcmp(current, "NAK", 3) == 0) {
        pkt = git_pkt_new(GIT_PKT_NAK, current, 3);
        current += 3;
    }
    else {
        return GIT_PKT_ERROR_UNKNOWN;
    }

    if (!pkt)
        return GIT_PKT_ERROR_ALLOC;

    if (*head == NULL) {
        *head = pkt;
    }
    else {
        git_pkt *tmp = *head;
        while (tmp->next != NULL) {
            tmp = tmp->next;
        }
        tmp->next = pkt;
    }

    *out = current;
    return GIT_PKT_OK;
}

int parse_git_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return GIT_PKT_ERROR_SHORT_BUFFER;
    }

    size_t pkt_len;
    if (memcmp(line, "ACK", 3) == 0) {
        pkt_len = 4;
    } else if (memcmp(line, "NAK", 3) == 0) {
        pkt_len = 4;
    } else if (memcmp(line, "SIDEBAND", 8) == 0) {
        int len;
        if (sscanf(line + 8, "%d", &len) != 1) {
            return GIT_PKT_ERROR_INVALID_FORMAT;
        }
        pkt_len = 8 + snprintf(NULL, 0, "%d", len);
    } else {
        pkt_len = 4;
    }

    if (bufflen < pkt_len) {
        return GIT_PKT_ERROR_SHORT_BUFFER;
    }

    git_pkt *pkt = malloc(sizeof(git_pkt));
    if (!pkt) {
        return GIT_PKT_ERROR_MALLOC_FAILED;
    }

    pkt->data = line;
    pkt->length = pkt_len;

    if (*head == NULL) {
        *head = pkt;
    } else {
        git_pkt *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = pkt;
    }

    *out = line + pkt_len;

    return 0;
}

int parse_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    size_t len;
    const char *ptr = line;
    int ret;

    if (bufflen < 4)
        return -1; // Insufficient buffer length

    len = (size_t)strtoul(ptr, NULL, 16);
    ptr += 4;

    if (len == 0) {
        *out = ptr;
        return 0;
    }

    if (bufflen < len)
        return -1; // Not enough data for the packet

    if (!memcmp(ptr, "data", 4)) {
        ret = handle_pkt_data(head, ptr, out);
    } else if (!memcmp(ptr, "sideband", 8)) {
        ret = handle_sideband_pkt(head, ptr, out);
    } else if (!memcmp(ptr, "ACK", 3)) {
        ret = handle_ack_pkt(head, ptr, out);
    } else {
        ret = handle_unknown_pkt(head, ptr, out);
    }

    if (ret < 0)
        return ret;

    *head = *head ? (*head)->next : *head;
    return 0;
}

